from mb_misc import mb_html
from mb_author import author
from mb_author.claim import ClaimCollection
from author_misc import mp_cmn as cmn
from author_misc import mpplain_body as body

_FNAME = "mpplain.html"
_TITLE = "Reading MAM-parsed-plain"


def gen_html_file(tdm_ch, claims: ClaimCollection):
    """Generate mpplain.html in the given output directory."""
    cbody = build_body(claims=claims)
    return author.help_gen_html_file(__file__, tdm_ch, _FNAME, _TITLE, cbody)


# ---------------------------------------------------------------------------
# Body builder
# ---------------------------------------------------------------------------


def build_body(*, claims: ClaimCollection):
    file_naming_rows = cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.file-naming.book24-prefixes",
    )
    return [
        mb_html.heading_level_1(_TITLE),
        *body.s_intro(),
        *cmn.s_file_naming(file_naming_rows=file_naming_rows),
        *body.s_top_level(claims=claims),
        *body.s_book39(claims=claims),
        *body.s_chapter(claims=claims),
        *body.s_template_format(claims=claims),
        *body.s_verse(claims=claims),
        *body.s_common_templates(claims=claims),
        *body.s_pseudo_verses(),
    ]


def _build_body(*, claims: ClaimCollection):
    return build_body(claims=claims)
